+	}
+	if m := a.Limits.MaxDurationMinutes; m < 0 || time.Duration(m)*time.Minute > maxAutomationDuration {
+		return nil, badAutomation("limits.max_duration_minutes must be at most %d",
+			int(maxAutomationDuration.Minutes()))
+	}
+	return sched, nil
