+	run := &types.AutomationRun{
+		AutomationID: a.ID, TenantID: a.TenantID, ScheduledAt: s.now().UTC().Truncate(time.Millisecond),
+		TriggerKind: types.AutomationRunManual, Status: types.AutomationRunQueued,
